const CardTitle = forwardRef<ComponentRef<typeof ark.h3>, HTMLArkProps<'h3'>>(function CardTitle(
  { className, ...props },
  ref,
) {
  return (
    <ark.h3
      ref={ref}
      className={clsx(styles.title, className)}
      {...props}
      data-scope="card"
      data-part="title"
      data-slot="card-title"
    />
  );
});

const CardDescription = forwardRef<ComponentRef<typeof ark.p>, HTMLArkProps<'p'>>(
  function CardDescription({ className, ...props }, ref) {
    return (
      <ark.p
        ref={ref}
        className={clsx(styles.description, className)}
        {...props}
        data-scope="card"
        data-part="description"
        data-slot="card-description"
      />
    );
  },
);

const CardAction = forwardRef<ComponentRef<typeof ark.div>, HTMLArkProps<'div'>>(
  function CardAction({ className, ...props }, ref) {
    return (
      <ark.div
        ref={ref}
        className={clsx(styles.action, className)}
        {...props}
        data-scope="card"
        data-part="action"
        data-slot="card-action"
      />
    );
  },
);

const CardLink = forwardRef<ComponentRef<typeof ark.a>, HTMLArkProps<'a'>>(function CardLink(
  { className, ...props },
  ref,
) {
  return (
    <ark.a
      ref={ref}
      className={clsx(styles.link, className)}
      {...props}
      data-scope="card"
      data-part="link"
      data-slot="card-link"
    />
  );
});

export {
  Card,
  CardAction,
  CardBackground,
  CardBody,
  CardDescription,
  CardFooter,
  CardHeader,
  CardLink,
  CardMedia,
  CardTitle,
};
export type { CardRootProps, CardSize, CardVariant };

@layer moduix.components {
  .root {
    --_card-spacing: var(--moduix-spacing-6);
    --_card-radius: var(--moduix-card-radius, var(--moduix-radius-lg));
    --_card-bg: var(--moduix-color-card);
    --_card-border-width: var(--moduix-border-width-sm);
    --_card-shadow: none;
    --_card-title-font-size: var(--moduix-text-lg);
    --_card-title-line-height: var(--moduix-line-height-text-lg);

    position: relative;
    display: flex;
    width: 100%;
    min-width: 0;
    flex-direction: column;
    border: var(--moduix-card-border-width, var(--_card-border-width)) solid
      var(--moduix-card-border-color, var(--moduix-color-border));
    border-radius: var(--_card-radius);
    background-color: var(--moduix-card-bg, var(--_card-bg));
    color: var(--moduix-card-color, var(--moduix-color-card-foreground));
    box-shadow: var(--moduix-card-shadow, var(--_card-shadow));

    &:where(a) {
      text-decoration: none;
    }

    &:focus-visible {
      outline: var(--moduix-focus-ring-width, var(--moduix-border-width-md)) solid
        var(--moduix-color-ring);
      outline-offset: var(--moduix-border-width-sm);
    }

    &[data-size='sm'] {
      --_card-spacing: var(--moduix-spacing-4);
      --_card-title-font-size: var(--moduix-text-md);
      --_card-title-line-height: var(--moduix-line-height-text-md);
    }

    &[data-size='lg'] {
      --_card-spacing: var(--moduix-spacing-8);
      --_card-title-font-size: var(--moduix-text-xl);
      --_card-title-line-height: var(--moduix-line-height-text-xl);
    }

    &[data-variant='elevated'] {
      --_card-border-width: 0;
      --_card-shadow: var(--moduix-shadow-md);
    }

    &[data-variant='subtle'] {
      --_card-bg: var(--moduix-color-muted);
      --_card-border-width: 0;
    }

    &:has(> .background) {
      isolation: isolate;
    }

    /* Keep nested controls above the stretched CardLink target. */
    &:has(.link)
      :where(
        a,
        button,
        input,
        select,
        textarea,
        summary,
        audio[controls],
        video[controls],
        iframe,
        [contenteditable='true'],
        [role='button'],
        [role='checkbox'],
        [role='menuitem'],
        [role='switch'],
        [tabindex]:not([tabindex='-1'])
      ):not(.link) {
      position: relative;
      z-index: 1;
    }
  }

  .header,
  .body,
  .footer {
    min-width: 0;
    padding: var(--moduix-card-spacing, var(--_card-spacing));
    padding-block-end: 0;

    &:last-child {
      padding-block-end: var(--moduix-card-spacing, var(--_card-spacing));
    }
  }

  .header {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    gap: var(--moduix-spacing-1) var(--moduix-spacing-2);
  }

  .body {
    font-size: var(--moduix-text-sm);
    line-height: var(--moduix-line-height-text-sm);
    overflow-wrap: anywhere;
  }

  .footer {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--moduix-spacing-2);
  }

  .media {
    min-width: 0;
    overflow: hidden;
    border-start-start-radius: inherit;
    border-start-end-radius: inherit;

    & > :where(img, picture, video, canvas, svg, iframe),
    & > picture > img {
      display: block;
      width: 100%;
    }
  }

  .background {
    position: absolute;
    z-index: -1;
    inset: 0;
    overflow: hidden;
    border-radius: inherit;

    & > :where(img, picture, video, canvas, svg, iframe),
    & > picture > img {
      display: block;
      width: 100%;
      height: 100%;
      object-fit: cover;
    }
  }

  .title {
    min-width: 0;
    font-size: var(--_card-title-font-size);
    font-weight: var(--moduix-weight-semibold);
    line-height: var(--_card-title-line-height);
    overflow-wrap: anywhere;
  }

  .description {
    min-width: 0;
    color: var(--moduix-color-muted-foreground);
    font-size: var(--moduix-text-sm);
    line-height: var(--moduix-line-height-text-sm);
    overflow-wrap: anywhere;
  }

  .action {
    position: relative;
    z-index: 1;
    grid-column: 2;
    grid-row: 1 / span 2;
    display: inline-flex;
    align-items: start;
    justify-content: flex-end;
    gap: var(--moduix-spacing-2);
  }

  .link {
    color: inherit;
    text-decoration: none;

    &::after {
      content: '';
      position: absolute;
      inset: 0;
      border-radius: var(--_card-radius);
    }

    &:focus-visible {
      outline: 0;
    }

    &:focus-visible::after {
      outline: var(--moduix-focus-ring-width, var(--moduix-border-width-md)) solid
        var(--moduix-color-ring);
      outline-offset: var(--moduix-border-width-sm);
    }
  }
}
